    ///
    /// Required permission: `company.read`.
    ///
    /// Returns one page. Use [`Self::get_all`] to iterate over every item.
    pub async fn get(self, params: &FeedGetParams) -> Result<Page<FeedPage>> {
        let request = Self::get_request(params)?;
        self.client.execute_page(request).await
    }

    /// Лента компании
    ///
    /// `GET /v1/companies/{co}/feed`
    ///
    /// Разделы: auto — сделано автоматически, decision — требует решения, question — вопросы от ИИ. Свежие сверху. Событие может появиться в базе позже более нового (время ставится до записи), то есть ниже уже виденного верха страницы. Опрашивая ленту за новым, читайте страницы, пока не дойдёте до событий на 30 с старше самого нового из виденных, и отсекайте повторы по id (событие с виденным id заменяет прежнее). Проще — поток …/feed/events с once=1 и курсором: он сам отдаёт это окно заново.
    ///
    /// Доступ: company.read.
